 for(const rv of RIVERS){if(dPoly(c.lat,c.lon,rv.p)<Math.max(rv.w,.74)){c.river=1;break}}
 c.urban=URBAN.some(u=>Math.hypot(X(u[1])-c.x,Z(u[0])-c.z)<u[2]);
 c.type=c.river?'river':c.e>520?'mtn':c.e>75?'hill':(c.coast&&c.e<40)?'sand':c.urban?'urban':'plain';
