PL.forEach(p=>{let m=1e9;PL.forEach(q=>{if(q!==p&&!q.bridge)m=Math.min(m,Math.hypot(p.x-q.x,p.z-q.z))});p.r=p.bridge?1.6:p.id==='chaotian'?2.6:p.id==='gongtian'?1.85:p.id==='qiumao'?1.25:Math.min(p.key?1.85:1.5,m/2-.3);p.s=p.r/1.85;p.h=p.bridge?.3:Math.max(heightAt(p.x,p.z),.3);p.top=p.h+.18*p.s});
